(function () {
  var HERO_WRAP_UID = "0189df0a-5823-4836-a68e-b222ed3a47d6";
  var HERO_READY_VAR = "dafc47f7-259a-4c95-a431-e28e229c6b46";
  var HERO_WRAP = ".ww-element-" + HERO_WRAP_UID;
  var STYLE_ID = "ww-hero-canvas-crop";
  var SPLASH_MIN_MS = 1200;
  var splashStarted = Date.now();
  var readyScheduled = false;

  function injectCropCss() {
    if (document.getElementById(STYLE_ID)) return;
    var css = [
      HERO_WRAP + "{overflow:hidden!important;background:#141f19!important;position:absolute!important;inset:0!important;width:100%!important;height:100%!important;}",
      HERO_WRAP + " iframe{position:absolute!important;top:50%!important;left:50%!important;width:177.78vh!important;height:56.25vw!important;min-width:100%!important;min-height:100%!important;transform:translate(-50%,-50%)!important;border:0!important;pointer-events:none!important;background:transparent!important;}",
      "html:not([data-ww-hero-video-ready=\"1\"]) " + HERO_WRAP + " iframe{opacity:0!important;visibility:hidden!important;}",
      "html[data-ww-hero-video-ready=\"1\"] " + HERO_WRAP + " iframe{opacity:1!important;visibility:visible!important;transition:opacity .65s ease;}",
      HERO_WRAP + "::after{content:\"\";position:absolute;inset:0;z-index:2;pointer-events:none;box-shadow:inset 0 0 0 1px rgba(198,161,91,0.22);}"
    ].join("\n");
    var el = document.createElement("style");
    el.id = STYLE_ID;
    el.textContent = css;
    document.head.appendChild(el);
  }

  function markReady() {
    if (readyScheduled) return;
    readyScheduled = true;
    var elapsed = Date.now() - splashStarted;
    var delay = Math.max(0, SPLASH_MIN_MS - elapsed);
    window.setTimeout(function () {
      document.documentElement.setAttribute("data-ww-hero-video-ready", "1");
      variables[HERO_READY_VAR] = true;
    }, delay);
  }

  function watchIframe() {
    var wrap = document.querySelector(HERO_WRAP);
    if (!wrap) { markReady(); return; }
    var iframe = wrap.querySelector("iframe");
    if (!iframe) { window.setTimeout(watchIframe, 100); return; }
    iframe.addEventListener("load", function () { markReady(); }, { once: true });
    window.setTimeout(markReady, 2000);
  }

  injectCropCss();
  watchIframe();
  return true;
})();
return true;

